import re

BASE = "https://www.revisor.mn.gov"

def chapter_sections(html):
    # the subdivision headnote sits inside the "Subd. 2." h2 and the permalink anchor is a bare "§": space the one, blank the other
    html = html.replace('<span class="headnote">', ' <span class="headnote">')
    html = re.sub(r'(<a [^>]*class="permalink"[^>]*>)§</a>', r'\1</a>', html)
    for t in block_texts(html, cls="section"):
        first, _, body = t.partition("\n")
        m = re.match(r"^(\d+[A-Z]*\.[0-9][0-9A-Z.\-]*)\s*(.*)$", first)
        if not m:
            log("odd section head %r" % first[:60]); continue
        yield m.group(1), m.group(2).strip(), body.strip()

def sections():
    k, toc = fetch(BASE + "/statutes/")
    parts = []
    for h in re.findall(r'href="(https://www\.revisor\.mn\.gov/statutes/part/[^"]+)"', toc):
        if h not in parts:
            parts.append(h)
    log("parts %d" % len(parts))
    seen = set()
    for pu in parts:
        try:
            k, page = fetch(pu)
        except Exception as e:
            log("part failed %s: %s" % (pu, e)); continue
        chs = []
        for c in re.findall(r'href="https://www\.revisor\.mn\.gov/statutes/cite/([0-9]+[A-Z]*)"', page):
            if c not in chs:
                chs.append(c)
        for ch in chs:
            url = "%s/statutes/cite/%s/full" % (BASE, ch)
            try:
                k, html = fetch(url)
            except Exception as e:
                log("chapter %s failed: %s" % (ch, e)); continue
            n = 0
            for sid, head, text in chapter_sections(html):
                if sid in seen or not text:
                    continue
                seen.add(sid); n += 1
                yield {"id": sid, "heading": head, "text": text, "url": url + "#stat." + sid}
            if not n:
                log("chapter %s: no live sections" % ch)
